typedef unsigned int u_int;

extern float WAVE_MeshMinX;
extern float WAVE_MeshMaxX;
extern u_int WAVE_MeshStepX;
#define WAVE_MESHSTEPMAXX 50
extern float WAVE_MeshGridX[WAVE_MESHSTEPMAXX+1];
extern float WAVE_SliceGridX[WAVE_MESHSTEPMAXX+1];
extern bool WAVE_LeftBreaker;
static float WAVE_WorldToProfile(float x);

__asm__(".equ WAVE_MeshMinX, 0x00484620");
__asm__(".equ WAVE_MeshMaxX, 0x00484624");
__asm__(".equ WAVE_MeshStepX, 0x00484630");
__asm__(".equ WAVE_LeftBreaker, 0x004846C4");
__asm__(".equ WAVE_MeshGridX, 0x00485180");
__asm__(".equ WAVE_SliceGridX, 0x0048ADC0");
__asm__(".equ WAVE_WorldToProfile__Ff, 0x00377F10");

static void WAVE_ComputeSlices(void)
{
#ifdef DEBUG
	if (WaveDebug.BreakTest)
	{
		int numused;
		for (
			numused = WAVE_PerturbTest.num;
			fabsf(WAVE_PerturbTest.profilex[numused-1] - WAVE_PerturbTest.profilex[numused-2]) < 0.00001;
			--numused
		) continue;
		assert(numused > 0);
		WAVE_PerturbTest.numused = numused;

		WAVE_PerturbTest.Init();

		for (u_int i = 0; i <= WAVE_MeshStepX; ++i)
		{
			WAVE_SliceGridX[i] = WAVE_TestSlice(WAVE_MeshGridX[i]);
		}
	}
	else
#endif
	{
		// Lock edges to zero
		WAVE_SliceGridX[0] = WAVE_LeftBreaker ? WAVE_MeshMaxX : WAVE_MeshMinX;
		for (u_int i = 1; i < WAVE_MeshStepX; ++i)
		{
			WAVE_SliceGridX[i] = WAVE_WorldToProfile(WAVE_MeshGridX[i]);
		}
		WAVE_SliceGridX[WAVE_MeshStepX] = WAVE_LeftBreaker ? WAVE_MeshMinX : WAVE_MeshMaxX;
	}
}
